import numpy as np
from scipy.optimize import minimize

def objective(x):
    return np.sum(x**2) + (np.sum(x))**2

def constraint_sum(x):
    return np.abs(np.sum(x)) - 1.0

def check_n_optimization(n):
    # Try to find x such that objective(x) = 20 and |sum x| < 1 and |x_i| < 1
    # We can try to minimize (objective(x) - 20)^2 subject to |sum x| <= 0.9 and |x_i| <= 0.9

    def func(x):
        return (np.sum(x**2) + (np.sum(x))**2 - 20)**2

    # Try multiple random starts
    for _ in range(10):
        x0 = np.random.uniform(-1, 1, n)
        res = minimize(func, x0, bounds=[(-0.99, 0.99)]*n, 
                       constraints={'type': 'ineq', 'fun': lambda x: 0.99 - np.abs(np.sum(x))})
        if res.fun < 1e-6:
            return True
    return False

for n in range(20, 23):
    print(f"n={n}, possible={check_n_optimization(n)}")
